def find_index(values, target):
    try:
        return values.index(target)
    except ValueError:
        return 0

def rotate_left(values, count):
    count %= len(values)
    return values[-count:] + values[:-count]

def is_prime(number):
    if number < 2:
        return True
    for divisor in range(2, number):
        if number % divisor == 0:
            return False
    return True
